function OverviewPlus({ stats, t }) { const daily=Object.entries(stats.daily).slice(-10); const best=Object.entries(stats.best).sort((a,b)=>b[1]-a[1]).slice(0,5); const stops=Object.entries(stats.stops).sort((a,b)=>b[1]-a[1]).slice(0,5); return <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={CircleDollarSign} label={t.sales} value={money(stats.sales)} note={`${stats.sold} ${t.sold.toLowerCase()}`} color="emerald" /><Metric icon={CreditCard} label={t.square} value={money(stats.square)} note="Square payments received" color="violet" /><Metric icon={Users} label={t.commission} value={money(stats.sales * commissionRate)} note="30% to pay drivers" color="amber" /><Metric icon={UtensilsCrossed} label={t.returned} value={stats.returned} note={`${money(stats.returnedValue)} ${t.potentialSales}`} color="rose" /></section><section className="mt-4 grid gap-4 xl:grid-cols-5"><div className="card p-5 xl:col-span-3"><SectionTitle title={t.activity} sub={t.activitySub} /><LineGraph daily={daily} /></div><div className="card p-5 xl:col-span-2"><SectionTitle title={t.food} sub={t.foodSub} />{best.length?<div className="mt-4 space-y-4">{best.map(([name,count])=><div key={name}><div className="flex justify-between gap-3 text-sm"><span className="truncate font-medium">{name}</span><span className="number">{count}</span></div><div className="mt-2 h-2 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-violet-500" style={{width:`${count/best[0][1]*100}%`}} /></div></div>)}</div>:<p className="mt-6 text-sm text-slate-400">{t.noSales}</p>}</div></section><section className="card mt-4 p-5"><SectionTitle title={t.stops} sub={t.stopsSub} />{stops.length?<div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-5">{stops.map(([name,value],index)=><div key={name} className="rounded-xl border bg-slate-50 p-4"><div className="flex items-center justify-between"><span className="grid h-7 w-7 place-items-center rounded-lg bg-emerald-100 text-xs font-bold text-emerald-700">{index+1}</span><Store size={16} className="text-slate-400" /></div><p className="mt-3 truncate text-sm font-bold">{name}</p><p className="mt-1 text-lg font-bold tracking-tight text-emerald-700">{money(value)}</p></div>)}</div>:<p className="mt-6 text-sm text-slate-400">{t.noSales}</p>}</section></> }
function LineGraph({ daily }) { if(!daily.length) return <div className="grid h-56 place-items-center text-sm text-slate-400">No sales yet.</div>; const values=daily.map(([,value])=>value); const rawMax=Math.max(...values,1); const magnitude=10**Math.floor(Math.log10(rawMax)); const max=Math.ceil(rawMax/(magnitude/2))*(magnitude/2); const width=720, height=250, left=58, right=18, top=18, bottom=36, plotHeight=height-top-bottom, plotWidth=width-left-right, tickCount=4; const moneyAxis=value=>value>=1000?`$${(value/1000).toFixed(value%1000?1:0)}k`:`$${Math.round(value)}`; const ticks=Array.from({length:tickCount+1},(_,index)=>max/tickCount*index); const gap=Math.min(28,plotWidth/Math.max(daily.length*3,1)); const barWidth=Math.min(72,Math.max(26,(plotWidth-gap*(daily.length-1))/daily.length)); const xFor=index=>left+(plotWidth/daily.length)*index+(plotWidth/daily.length-barWidth)/2; const yFor=value=>top+plotHeight-(value/max)*plotHeight; return <div className="mt-4"><svg viewBox={`0 0 ${width} ${height}`} className="h-60 w-full" role="img" aria-label="Daily sales bar chart with dollar scale">{ticks.map(value=>{const y=yFor(value);return <g key={value}><line x1={left} y1={y} x2={width-right} y2={y} stroke="#e2e8f0" strokeDasharray={value===0?'0':'4 5'}/><text x={left-10} y={y+4} textAnchor="end" className="fill-slate-400 text-[11px] font-medium">{moneyAxis(value)}</text></g>})}<line x1={left} y1={top} x2={left} y2={height-bottom} stroke="#cbd5e1"/>{daily.map(([date,value],index)=>{const x=xFor(index), y=yFor(value), barHeight=height-bottom-y; return <g key={date}><rect x={x} y={y} width={barWidth} height={barHeight} rx="7" fill="#10b981"/><text x={x+barWidth/2} y={y-9} textAnchor="middle" className="fill-emerald-700 text-[11px] font-bold">{money(value)}</text><text x={x+barWidth/2} y={height-11} textAnchor="middle" className="fill-slate-400 text-[11px] font-medium">{date.slice(5)}</text></g>})}</svg></div> }
function Overview({ stats }) { const daily = Object.entries(stats.daily).slice(-8); const max = Math.max(...daily.map(([, value]) => value), 1); const best = Object.entries(stats.best).sort((a,b) => b[1] - a[1]).slice(0, 5); return <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={CircleDollarSign} label="Total sales" value={money(stats.sales)} note={`${stats.sold} items sold`} color="emerald" /><Metric icon={Users} label="Driver commission" value={money(stats.sales * commissionRate)} note="30% to pay drivers" color="violet" /><Metric icon={ClipboardList} label="Cash expected" value={money(stats.cash)} note="Cash collected" color="amber" /><Metric icon={UtensilsCrossed} label="Returned food" value={stats.returned} note="Possible missed sales" color="rose" /></section><section className="mt-4 grid gap-4 xl:grid-cols-5"><div className="card p-5 xl:col-span-3"><SectionTitle title="Sales activity" sub="Sales from all drivers" /><div className="mt-6 flex h-48 items-end gap-3 border-b px-2">{daily.length ? daily.map(([date, value]) => <div key={date} className="flex h-full min-w-0 flex-1 flex-col justify-end gap-2 text-center"><span className="text-[10px] font-bold text-slate-500">{money(value)}</span><div className="rounded-t-md bg-gradient-to-t from-emerald-600 to-emerald-400" style={{ height: `${Math.max(5, value / max * 100)}%` }} /><span className="text-[10px] text-slate-400">{date.slice(5)}</span></div>) : <div className="m-auto text-sm text-slate-400">No sales yet.</div>}</div></div><div className="card p-5 xl:col-span-2"><SectionTitle title="Top selling food" sub="Most items sold" />{best.length ? <div className="mt-4 space-y-4">{best.map(([name, count]) => <div key={name}><div className="flex justify-between gap-3 text-sm"><span className="truncate font-medium">{name}</span><span className="number">{count}</span></div><div className="mt-2 h-2 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-violet-500" style={{ width: `${count / best[0][1] * 100}%` }} /></div></div>)}</div> : <p className="mt-6 text-sm text-slate-400">No sales yet.</p>}</div></section></> }
function Metric({ icon: Icon, label, value, note, color }) { const colors = { emerald: 'bg-emerald-50 text-emerald-600', violet: 'bg-violet-50 text-violet-600', amber: 'bg-amber-50 text-amber-600', rose: 'bg-rose-50 text-rose-600' }; return <article className="card p-5"><div className="flex items-center justify-between"><span className="text-sm font-semibold text-slate-500">{label}</span><span className={`grid h-9 w-9 place-items-center rounded-xl ${colors[color]}`}><Icon size={18} /></span></div><div className="mt-5 text-3xl font-bold tracking-tight">{value}</div><p className="mt-1 text-xs text-slate-400">{note}</p></article> }
