function Drivers({ drivers, t }) { const rows = drivers.map(driver => { let sold = 0, returned = 0, sales = 0; driver.days.forEach(day => { sold += soldCount(day); returned += returnedCount(day); sales += dayRevenue(day) }); return { ...driver, sold, returned, taken: sold + returned, sales } }).sort((a,b) => b.sales - a.sales); return <section className="card overflow-hidden"><div className="border-b p-5"><SectionTitle title={t.driverPerformance} sub={t.driverNote} /></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-sm"><thead className="bg-slate-50 text-left text-[11px] uppercase tracking-wider text-slate-400"><tr><th className="px-5 py-3">{t.driver}</th><th className="px-4 py-3 text-right">{t.taken}</th><th className="px-4 py-3 text-right">{t.sold}</th><th className="px-4 py-3 text-right">{t.returns}</th><th className="px-4 py-3 text-right">{t.revenue}</th><th className="px-5 py-3 text-right">{t.commission}</th></tr></thead><tbody>{rows.map(driver => <tr key={driver.id} className="border-t"><td className="px-5 py-4"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-gradient-to-br from-emerald-500 to-teal-600 text-xs font-bold text-white">{driver.name.slice(0,2).toUpperCase()}</span><span className="font-semibold">{driver.name}</span></div></td><td className="number px-4 py-4 text-right">{driver.taken}</td><td className="number px-4 py-4 text-right">{driver.sold}</td><td className="number px-4 py-4 text-right">{driver.returned}</td><td className="number px-4 py-4 text-right">{money(driver.sales)}</td><td className="number px-5 py-4 text-right text-emerald-700">{money(driver.sales * commissionRate)}</td></tr>)}{!rows.length && <tr><td colSpan="6" className="px-5 py-12 text-center text-slate-400">{t.noDrivers}</td></tr>}</tbody></table></div></section> }
function SettingsPanel({ menu, labels, actualDrivers, manualDrivers, message, changePrice, addProduct, removeProduct, addDriver, removeDriver, setLabels, saveMenu, saveDrivers }) { const [day, setDay] = useState(days.includes(new Date().toLocaleDateString('en-US', { weekday: 'long' })) ? new Date().toLocaleDateString('en-US', { weekday: 'long' }) : 'Monday'); const people = [...actualDrivers.map(d => ({ ...d, manual: false })), ...manualDrivers.filter(d => !actualDrivers.some(actual => actual.id === d.id)).map(d => ({ id: d.id, name: labels[d.id] || d.name, manual: true }))]; if (!menu) return <Loading />; return <div className="grid gap-4 xl:grid-cols-3"><section className="card p-5 xl:col-span-2"><div className="flex flex-col justify-between gap-3 border-b pb-4 sm:flex-row sm:items-center"><SectionTitle title="Menu and prices" sub="Changes apply to future sales only." /><div className="flex gap-2"><select value={day} onChange={e => setDay(e.target.value)} className="h-9 rounded-lg border bg-white px-2 text-sm font-semibold">{days.map(d => <option key={d}>{d}</option>)}</select><button onClick={saveMenu} className="rounded-lg bg-emerald-600 px-3 text-sm font-bold text-white hover:bg-emerald-700">Save menu</button></div></div><div className="mt-2 divide-y">{Object.entries(menu[day] || {}).map(([category, items]) => <div key={category} className="py-4"><div className="mb-2 flex items-center justify-between"><h3 className="text-sm font-bold">{category}</h3><button onClick={() => addProduct(day, category)} className="inline-flex items-center gap-1 text-xs font-bold text-emerald-700"><PackagePlus size={15} /> Add</button></div>{items.map(([name, price], index) => <div key={`${name}-${index}`} className="grid grid-cols-[1fr_88px_32px] gap-2 py-1"><span className="truncate self-center text-sm font-medium">{name}</span><input value={price} onChange={e => changePrice(day, category, index, e.target.value)} type="number" min="0" step=".01" className="h-9 rounded-lg border px-2 text-right text-sm font-bold" /><button onClick={() => removeProduct(day, category, index)} className="icon-button !h-8 !w-8 text-rose-500" title="Remove product"><Trash2 size={15} /></button></div>)}</div>)}</div></section><section className="card h-fit p-5"><div className="flex items-start justify-between border-b pb-4"><SectionTitle title="Drivers" sub="Names shown on the dashboard." /><button onClick={addDriver} className="icon-button text-emerald-700" title="Add driver"><Users size={16} /></button></div><div className="mt-4 space-y-3">{people.map(person => <div key={person.id} className="rounded-xl border bg-slate-50 p-3"><p className="mb-1 text-[10px] font-bold uppercase tracking-wider text-slate-400">{person.id}{person.manual ? ' · new' : ''}</p><div className="flex gap-2"><input value={labels[person.id] ?? person.name} onChange={e => setLabels(current => ({ ...current, [person.id]: e.target.value }))} className="min-w-0 flex-1 rounded-lg border bg-white px-2 text-sm font-semibold" />{person.manual && <button onClick={() => removeDriver(person.id)} className="icon-button !h-8 !w-8 text-rose-500"><Trash2 size={14} /></button>}</div></div>)}{!people.length && <p className="text-sm text-slate-400">Add a future driver here. They appear in performance after their first app sync.</p>}</div><button onClick={saveDrivers} className="mt-4 w-full rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm font-bold text-emerald-700 hover:bg-emerald-100">Save driver list</button></section>{message && <div className="xl:col-span-3 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800">{message}</div>}</div> }

function SettingsPanel2({ menu, labels, actualDrivers, manualDrivers, message, changePrice, addProduct, removeProduct, addDriver, removeDriver, setLabels, saveMenu, saveDrivers, t }) { const [day,setDay]=useState(days.includes(new Date().toLocaleDateString('en-US',{weekday:'long'}))?new Date().toLocaleDateString('en-US',{weekday:'long'}):'Monday'); const [newName,setNewName]=useState(''); const people=[...actualDrivers.map(d=>({...d,manual:false})),...manualDrivers.filter(d=>!actualDrivers.some(a=>a.id===d.id)).map(d=>({id:d.id,name:labels[d.id]||d.name,manual:true}))]; const submit=()=>{if(addDriver(newName.trim()))setNewName('')}; if(!menu)return <Loading />; return <div className="grid gap-4 xl:grid-cols-3"><section className="card p-5 xl:col-span-2"><div className="flex flex-col justify-between gap-3 border-b pb-4 sm:flex-row sm:items-center"><SectionTitle title={t.menu} sub={t.menuSub}/><div className="flex flex-wrap items-center gap-2"><span className="rounded-md bg-amber-50 px-2 py-1 text-xs font-bold text-amber-700">{t.dayOnly}: {day}</span><select value={day} onChange={e=>setDay(e.target.value)} className="h-9 rounded-lg border bg-white px-2 text-sm font-semibold">{days.map(d=><option key={d}>{d}</option>)}</select><button onClick={saveMenu} className="rounded-lg bg-emerald-600 px-3 text-sm font-bold text-white">{t.saveMenu}</button></div></div><div className="mt-2 divide-y">{Object.entries(menu[day]||{}).map(([category,items])=><div key={category} className="py-4"><div className="mb-2 flex items-center justify-between"><h3 className="text-sm font-bold">{category}</h3><button onClick={()=>addProduct(day,category)} className="inline-flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-bold text-emerald-700 hover:bg-emerald-50"><PackagePlus size={15}/>{t.addProduct}</button></div>{items.map(([name,price],index)=><div key={`${name}-${index}`} className="grid grid-cols-[1fr_88px_32px] gap-2 py-1"><span className="truncate self-center text-sm font-medium">{name}</span><input value={price} onChange={e=>changePrice(day,category,index,e.target.value)} type="number" min="0" step=".01" className="h-9 rounded-lg border px-2 text-right text-sm font-bold"/><button onClick={()=>removeProduct(day,category,index)} className="icon-button !h-8 !w-8 text-rose-500" title="Remove product"><Trash2 size={15}/></button></div>)}</div>)}</div></section><section className="card h-fit p-5"><SectionTitle title={t.driverList} sub={t.driverListSub}/><div className="mt-4 rounded-xl border bg-emerald-50 p-3"><label className="label">{t.addDriver}</label><div className="mt-2 flex gap-2"><input value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&submit()} placeholder={t.newDriver} className="min-w-0 flex-1 rounded-lg border bg-white px-3 text-sm font-semibold"/><button onClick={submit} className="rounded-lg bg-emerald-600 px-3 text-sm font-bold text-white">{t.addDriver}</button></div></div><div className="mt-4 space-y-3">{people.map(person=><div key={person.id} className="rounded-xl border bg-slate-50 p-3"><p className="mb-1 text-[10px] font-bold uppercase tracking-wider text-slate-400">{person.id}{person.manual?` · ${t.future}`:''}</p><div className="flex gap-2"><input value={labels[person.id]??person.name} onChange={e=>setLabels(current=>({...current,[person.id]:e.target.value}))} className="min-w-0 flex-1 rounded-lg border bg-white px-2 text-sm font-semibold"/>{person.manual&&<button onClick={()=>removeDriver(person.id)} className="icon-button !h-8 !w-8 text-rose-500" title="Remove driver"><Trash2 size={14}/></button>}</div></div>)}</div><button onClick={saveDrivers} className="mt-4 w-full rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm font-bold text-emerald-700">{t.saveDrivers}</button></section>{message&&<div className="xl:col-span-3 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800">{message}</div>}</div> }

function OverviewPlus2({ stats, t }) { const daily=Object.entries(stats.daily).slice(-10); const best=Object.entries(stats.best).sort((a,b)=>b[1]-a[1]).slice(0,5); const stops=Object.entries(stats.stops).sort((a,b)=>b[1]-a[1]).slice(0,5); return <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={CircleDollarSign} label={t.sales} value={money(stats.sales)} note={`${stats.sold} ${t.sold.toLowerCase()}`} color="emerald"/><Metric icon={CreditCard} label={t.square} value={money(stats.square)} note={t.squareNote} color="violet"/><Metric icon={Users} label={t.commission} value={money(stats.sales*commissionRate)} note={t.commissionNote} color="amber"/><Metric icon={UtensilsCrossed} label={t.returned} value={stats.returned} note={`${money(stats.returnedValue)} ${t.potentialSales}`} color="rose"/></section><section className="mt-4 grid gap-4 xl:grid-cols-5"><div className="card p-5 xl:col-span-3"><SectionTitle title={t.activity} sub={t.activitySub}/><LineGraph2 daily={daily} t={t}/></div><div className="card p-5 xl:col-span-2"><SectionTitle title={t.food} sub={t.foodSub}/>{best.length?<div className="mt-4 space-y-4">{best.map(([name,count])=><div key={name}><div className="flex justify-between gap-3 text-sm"><span className="truncate font-medium">{name}</span><span className="number">{count}</span></div><div className="mt-2 h-2 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-violet-500" style={{width:`${count/best[0][1]*100}%`}}/></div></div>)}</div>:<p className="mt-6 text-sm text-slate-400">{t.noSales}</p>}</div></section><section className="card mt-4 p-5"><SectionTitle title={t.stops} sub={t.stopsSub}/>{stops.length?<div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-5">{stops.map(([name,value],index)=><div key={name} className="rounded-xl border bg-slate-50 p-4"><div className="flex items-center justify-between"><span className="grid h-7 w-7 place-items-center rounded-lg bg-emerald-100 text-xs font-bold text-emerald-700">{index+1}</span><Store size={16} className="text-slate-400"/></div><p className="mt-3 truncate text-sm font-bold">{name}</p><p className="mt-1 text-lg font-bold tracking-tight text-emerald-700">{money(value)}</p></div>)}</div>:<p className="mt-6 text-sm text-slate-400">{t.noSales}</p>}</section></> }
function LineGraph2({ daily, t }) { if(!daily.length)return <div className="grid h-56 place-items-center text-sm text-slate-400">{t.noSales}</div>; return <LineGraph daily={daily}/> }
function SettingsPanel3({ menu, labels, actualDrivers, manualDrivers, message, changePrice, addProduct, removeProduct, addDriver, removeDriver, setLabels, saveMenu, saveDrivers, t }) { const [day,setDay]=useState(days.includes(new Date().toLocaleDateString('en-US',{weekday:'long'}))?new Date().toLocaleDateString('en-US',{weekday:'long'}):'Monday'); const [newName,setNewName]=useState(''); const people=[...actualDrivers.map(d=>({...d,manual:false})),...manualDrivers.filter(d=>!actualDrivers.some(a=>a.id===d.id)).map(d=>({id:d.id,name:labels[d.id]||d.name,manual:true}))]; const submit=()=>{if(addDriver(newName.trim()))setNewName('')}; if(!menu)return <Loading/>; return <div className="grid gap-4 xl:grid-cols-3"><section className="card p-5 xl:col-span-2"><div className="flex flex-col justify-between gap-3 border-b pb-4 sm:flex-row sm:items-center"><SectionTitle title={t.menu} sub={t.menuFuture}/><div className="flex flex-wrap items-center gap-2"><span className="rounded-md bg-amber-50 px-2 py-1 text-xs font-bold text-amber-700">{t.dayOnly}: {day}</span><select aria-label={t.selectDay} value={day} onChange={e=>setDay(e.target.value)} className="h-9 rounded-lg border bg-white px-2 text-sm font-semibold">{days.map(d=><option key={d}>{d}</option>)}</select><button onClick={saveMenu} className="rounded-lg bg-emerald-600 px-3 text-sm font-bold text-white">{t.saveMenu}</button></div></div><div className="mt-2 divide-y">{Object.entries(menu[day]||{}).map(([category,items])=><div key={category} className="py-4"><div className="mb-2 flex items-center justify-between"><h3 className="text-sm font-bold">{category}</h3><button onClick={()=>addProduct(day,category)} className="inline-flex items-center gap-1 rounded-lg px-2 py-1 text-xs font-bold text-emerald-700 hover:bg-emerald-50"><PackagePlus size={15}/>{t.addProduct}</button></div>{items.map(([name,price],index)=><div key={`${name}-${index}`} className="grid grid-cols-[1fr_88px_76px] gap-2 py-1"><span className="truncate self-center text-sm font-medium">{name}</span><input value={price} onChange={e=>changePrice(day,category,index,e.target.value)} type="number" min="0" step=".01" className="h-9 rounded-lg border px-2 text-right text-sm font-bold"/><button onClick={()=>removeProduct(day,category,index)} className="rounded-lg border border-rose-200 bg-rose-50 px-2 text-xs font-bold text-rose-700" title={t.removeProduct}><Trash2 className="mr-1 inline" size={14}/>{t.remove}</button></div>)}</div>)}</div></section><section className="card h-fit p-5"><SectionTitle title={t.driverList} sub={t.driverListSub}/><div className="mt-4 rounded-xl border bg-emerald-50 p-3"><label className="label">{t.addDriver}</label><div className="mt-2 flex gap-2"><input value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&submit()} placeholder={t.newDriver} className="min-w-0 flex-1 rounded-lg border bg-white px-3 text-sm font-semibold"/><button onClick={submit} className="rounded-lg bg-emerald-600 px-3 text-sm font-bold text-white">{t.addDriver}</button></div></div><div className="mt-4 space-y-3">{people.map(person=><div key={person.id} className="rounded-xl border bg-slate-50 p-3"><p className="mb-1 text-[10px] font-bold uppercase tracking-wider text-slate-400">{person.id}{person.manual?` · ${t.future}`:''}</p><div className="flex gap-2"><input value={labels[person.id]??person.name} onChange={e=>setLabels(current=>({...current,[person.id]:e.target.value}))} className="min-w-0 flex-1 rounded-lg border bg-white px-2 text-sm font-semibold"/>{person.manual&&<button onClick={()=>removeDriver(person.id)} className="rounded-lg border border-rose-200 bg-rose-50 px-3 text-xs font-bold text-rose-700" title={t.removeDriver}><Trash2 className="mr-1 inline" size={14}/>{t.remove}</button>}</div>{!person.manual&&<p className="mt-2 text-xs text-slate-400">{t.futureOnly}</p>}</div>)}</div><button onClick={saveDrivers} className="mt-4 w-full rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm font-bold text-emerald-700">{t.saveDrivers}</button></section>{message&&<div className="xl:col-span-3 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800">{message}</div>}</div> }
function SettingsPanel4({ actualDrivers, manualDrivers, ...props }) { const displayDrivers=[...actualDrivers.map(driver=>({ id:driver.id, name:driver.name })), ...manualDrivers]; return <SettingsPanel3 {...props} t={{...props.t,future:''}} actualDrivers={[]} manualDrivers={displayDrivers} /> }
createRoot(document.getElementById('root')).render(<App />)
